add_shortcode( 'customers_only', 'perfectpixel_customers_only_shortcode' );

function perfectpixel_customers_only_shortcode( $atts, $content = '' ) {
	$atts    = shortcode_atts( array( 'product' => '' ), $atts );
	$allowed = false;
	if ( is_user_logged_in() ) {
		$user = wp_get_current_user();
		$ids  = wp_parse_id_list( $atts['product'] );
		if ( $ids ) {
			foreach ( $ids as $id ) {
				if ( wc_customer_bought_product( $user->user_email, $user->ID, $id ) ) {
					$allowed = true;
					break;
				}
			}
		} else {
			// Any paid order counts.
			$allowed = (bool) wc_get_orders( array( 'customer_id' => $user->ID, 'status' => wc_get_is_paid_statuses(), 'limit' => 1, 'return' => 'ids' ) );
		}
	}
	if ( $allowed ) {
		return do_shortcode( $content );
	}
	$message = trim( '{{customers_only_message}}' );
	return '' !== $message ? '<div class="woocommerce-info perfectpixel-customers-only">' . esc_html( $message ) . '</div>' : '';
}
